outcome.summary:
{
  "observations": [
    {
      "source_id": "change",
      "quote": "At 07:00 UTC only orders-api image changed from r1 to r2. Replicas remained 2; there was no schema or configuration change."
    },
    {
      "source_id": "comparison",
 "quote": "At 07:01 UTC r2 returns 500 for the test request, while an r1 canary in the same namespace still returns 200 for that request against the same dependency."
    },
    {
 "source_id": "recovery-check",
 "quote": "At 07:02 UTC both r1 canary replicas are healthy; r1 image digest and deployment specification are available. No data migration occurred."
    }
  ],
  "cause_assessment": "The root cause is likely within the r2 image itself. When the service was updated to r2, it began returning 500 errors. The fact that the same dependency is functioning with the r1 image suggests the fault is within the r2 image itself. This aligns with the observation that the change was only the image.",
 "alternative_explanation": "An alternative explanation is that the r2 image interacts with the same dependency in a different way that causes the failure. This might include different error handling or the r2 image might have a bug that causes the failure. However, the fact that the same dependency is functioning with the r1 image makes the likelihood of the fault within the dependency itself less likely.",
 "recovery": "review_candidate",
 "recovery_reason": "The recovery option of reverting to r1 is supported because the r1 image is available and the r2 image is the only change from the previous state. The recovery process should review the r1 image to ensure it is stable and functional.",
 "next_read_only_checks": [
 "Validate the r1 image is functional with the same dependencies",
 "Validate the r2 image has known issues",
 "Validate the deployment configuration has not changed"
 ]
}

